export function filterGongCallsByEmail(calls, email, limit = 10) {
    const normalizedEmail = email.toLowerCase();
    return calls
        .filter((call) => (call.parties ?? []).some((party) => party.emailAddress?.toLowerCase() === normalizedEmail))
        .slice(0, limit)
        .map((call) => ({
        id: call.id,
        title: call.title,
        started: call.started,
        duration: call.duration,
        direction: call.direction,
        parties: (call.parties ?? []).map((party) => ({
            name: party.name,
            email: party.emailAddress,
        })),
    }));
}
export async function lookupGongCallsByEmail(options) {
    const fetchImpl = options.fetch ?? globalThis.fetch;
    const lookbackDays = options.lookbackDays ?? 90;
    const fromDateTime = new Date((options.now ?? Date.now()) - lookbackDays * 24 * 60 * 60 * 1000).toISOString();
    const url = `https://api.gong.io/v2/calls?fromDateTime=${fromDateTime}`;
    const authHeaders = [
        `Bearer ${options.credential}`,
        `Basic ${Buffer.from(options.credential).toString("base64")}`,
    ];
    try {
        let firstStatus = 502;
        for (const [index, authorization] of authHeaders.entries()) {
            const response = await fetchImpl(url, {
                headers: {
                    Authorization: authorization,
                    "Content-Type": "application/json",
                },
            });
            if (index === 0)
                firstStatus = response.status;
            if (!response.ok)
                continue;
            const data = (await response.json());
            return {
                ok: true,
                calls: filterGongCallsByEmail(data.calls ?? [], options.email, options.limit),
            };
        }
        return {
            ok: false,
            status: firstStatus,
            error: `Gong API error: ${firstStatus}`,
        };
    }
    catch {
        return { ok: false, status: 500, error: "Failed to reach Gong API" };
    }
}
